    0: "no",
    1: "one",
    2: "two",
    3: "three",
    4: "four",
    5: "five",
    6: "six",
    7: "seven",
    8: "eight",
    9: "nine",
    10: "Ten",
}


def _bottles(n):
    return "bottle" if n == 1 else "bottles"


def _verse(n):
    return [
        f"{NUMBERS[n]} green {_bottles(n)} hanging on the wall,",
        f"{NUMBERS[n]} green {_bottles(n)} hanging on the wall,",
        "And if one green bottle should accidentally fall,",
        f"There'll be {NUMBERS[n - 1]} green {_bottles(n - 1)} hanging on the wall.",
    ]


def recite(start, take=1):
    lines = []
    for i in range(start, start - take, -1):
        if lines:
            lines.append("")
        lines.extend(_verse(i))
    return lines
